import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { renderHook, type RenderHookOptions } from '@testing-library/react';

/**
 * Builds a fresh QueryClient per call — test isolation, no cache bleed between tests.
 * Matches `_app-config/index.tsx`'s real `defaultOptions` for retry/refetchOnWindowFocus so a
 * hook under test behaves the same as it does in the running app.
 */
const createTestQueryClient = () =>
  new QueryClient({
    defaultOptions: {
      queries: { retry: false, refetchOnWindowFocus: false },
    },
  });

/**
 * Renders a hook that calls `@tanstack/react-query`'s `useQuery` inside a fresh
 * `QueryClientProvider` — the same wrapper `_app-config`'s `withReactQuery(AppConfig, ...)`
 * mounts for every page in the real app, so a hook under test needs no provider of its own
 * beyond this. See `.claude/rules/testing.md` > Commerce SDK hooks for the equivalent
 * `renderWithProviders` pattern this mirrors for `CommerceApiProvider`-dependent hooks.
 *
 * @param callback the hook to render
 * @param options `renderHook` options other than `wrapper`, which this helper supplies
 * @returns the same result `@testing-library/react`'s `renderHook` returns
 */
export const renderHookWithQueryClient = <TResult, TProps>(
  callback: (props: TProps) => TResult,
  options?: Omit<RenderHookOptions<TProps>, 'wrapper'>,
) => {
  const queryClient = createTestQueryClient();
  return renderHook(callback, {
    ...options,
    wrapper: ({ children }) => <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>,
  });
};
